def max_fruits_sliced(n, points):
    def ccw(A, B, C):
        return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])

    def intersect(A, B, P, Q):
        return ccw(A, P, Q) != ccw(B, P, Q) and ccw(A, B, P) != ccw(A, B, Q)

    max_count = 0
    for i in range(n):
        count = 0
        for j in range(i + 1, n):
            A, B = points[i], points[j]
            for k in range(j + 1, n):
                P, Q = points[k], points[(k + 1) % n]
                if intersect(A, B, P, Q):
                    count += 1
        max_count = max(max_count, count)
    return max_count

